// SALIDA DE PERSONA, paso 1: ¿este toque es para este flujo?
//
// El flujo atiende UN numero (se instala por alias: la misma plantilla con otro
// `phoneNumberId` en `Config base`). Dos disparadores llegan aqui: el
// timbre de la Function (POST sin datos) y el barrido de cada minuto, que
// reclama igual por si un timbre se perdio.
//
// - Sin `phoneNumberId` configurado el flujo NO corre: un error visible en la
//   ejecucion, nunca un reclamo con un numero de marcador.
// - Un timbre que trae `X-NovuChat-Numero` de OTRO numero se descarta: la ruta
//   del webhook ya es de este numero, esto es solo un cinturon.
// - La clave y la firma del timbre las verifica el Header Auth del webhook; este
//   nodo no tiene `crypto` y no las toca.
const cfg = $('Config base').first().json;
const numero = String(cfg.phoneNumberId ?? '').trim();
if (!/^[0-9]{8,20}$/.test(numero)) {
  throw new Error('Salida de persona: Config base no tiene el phoneNumberId de este flujo.');
}

const timbre = $('Timbre');
let origen = 'barrido';
if (timbre.isExecuted) {
  origen = 'timbre';
  const cabeceras = (timbre.first().json.headers) || {};
  const deQuien = String(cabeceras['x-novuchat-numero'] ?? '').trim();
  if (deQuien && deQuien !== numero) return [];
}

return [{ json: { origen, phoneNumberId: numero } }];

// SALIDA DE PERSONA, paso 3: de la lista reclamada a un envio por mensaje.
//
// Entra la respuesta de `reclamarSalidaPersona`: { mensajes: [...] } con hasta 10
// mensajes ya pasados a `enviando`. Sale UN item por mensaje con lo que los nodos
// de envio necesitan. Lista vacia = fin del bucle (no sale ningun item).
//
// Un mensaje que NO se puede enviar por un defecto propio (canal que no es
// 'rele' ni 'graph', texto vacio, direccion invalida, rele sin configurar) lleva
// `sinEnvio` con un codigo: el Switch lo manda directo a `Resultado del envío`,
// que lo confirma como rechazado. Nunca se queda en `enviando` ni se envia a ciegas.
const cfg = $('Config base').first().json;
const entrada = $input.all()[0];
const lista = entrada && entrada.json && Array.isArray(entrada.json.mensajes) ? entrada.json.mensajes : [];
const releBase = String(cfg.releBaseUrl ?? '').trim();
const releListo = /^http:\/\/[A-Za-z0-9._-]+(:[0-9]{2,5})?$/.test(releBase);

const salida = [];
for (const m of lista) {
  const p = (m && typeof m === 'object') ? m : {};
  const mensajeId = String(p.mensajeId ?? '');
  const conversacionId = String(p.conversacionId ?? '');
  const texto = typeof p.texto === 'string' ? p.texto : '';
  const to = String(p.to ?? '');
  const canal = String(p.canal ?? '');
  const claveRele = String(p.claveRele ?? '');

  let sinEnvio = '';
  let reintentable = false;
  if (!mensajeId || !conversacionId) sinEnvio = 'NV-RECLAMO';
  else if (canal !== 'rele' && canal !== 'graph') sinEnvio = 'NV-CANAL';
  else if (!/^[0-9]{8,15}$/.test(to)) sinEnvio = 'NV-DESTINO';
  else if (texto.trim() === '' || texto.length > 1000) sinEnvio = 'NV-TEXTO';
  else if (canal === 'rele' && !/^[A-Za-z0-9_.:-]{16,128}$/.test(claveRele)) sinEnvio = 'NV-CLAVE';
  else if (canal === 'rele' && !releListo) { sinEnvio = 'NV-RELE-CONFIG'; reintentable = true; }

  salida.push({ json: {
    mensajeId, conversacionId, canal, claveRele,
    sinEnvio, reintentable,
    // Por donde sigue el Switch: un mensaje con defecto propio NUNCA entra a un nodo de envio.
    ruta: sinEnvio ? 'ninguna' : canal,
    // Mismo cuerpo para el rele y para Graph: el rele reenvia a Graph tal cual.
    cuerpoEnvio: { messaging_product: 'whatsapp', to, type: 'text', text: { body: texto } },
  }});
}
return salida;

// SALIDA DE PERSONA, paso 5: de la respuesta del rele o de Graph al resultado
// que se confirma. Se ejecuta una vez por mensaje (modo "cada item").
//
// Reglas (contrato H2 §4; rele B9 y Graph):
//   2xx con id de mensaje ........................ aceptado + idMeta
//   2xx sin id legible ........................... incierto (Meta pudo aceptarlo)
//   error de red, tiempo agotado, 504, WM-3041 ... incierto: NUNCA se reenvia solo
//   5xx sin codigo, WM-3030/3035/3042 ............ incierto
//   codigo de Meta o del rele (4xx / WM-3040) .... rechazado + codigo (+ reintentable)
//   sin envio por defecto propio ................. rechazado + codigo NV-*
// El texto del mensaje nunca sale de este nodo.
const p = $('Planificar lote').item.json;
const r = $input.item.json;

const base = { mensajeId: p.mensajeId, conversacionId: p.conversacionId };
const limpio = (v) => String(v ?? '').replace(/[^A-Za-z0-9_.-]/g, '_').slice(0, 40) || 'DESCONOCIDO';
const rechazo = (codigo, reintentable) => ({ json: { ...base, resultado: 'rechazado', codigo: limpio(codigo), reintentable: reintentable === true } });
const incierto = () => ({ json: { ...base, resultado: 'incierto' } });

if (p.sinEnvio) return rechazo(p.sinEnvio, p.reintentable === true);

// Un error del nodo HTTP (red, tiempo agotado): el mensaje pudo salir.
if (r.error !== undefined && r.statusCode === undefined) return incierto();

const estado = Number(r.statusCode);
let cuerpo = r.body;
if (typeof cuerpo === 'string') { try { cuerpo = JSON.parse(cuerpo); } catch (e) { cuerpo = {}; } }
if (cuerpo === null || typeof cuerpo !== 'object') cuerpo = {};

if (estado >= 200 && estado < 300) {
  const primero = Array.isArray(cuerpo.messages) ? cuerpo.messages[0] : undefined;
  const id = primero && typeof primero.id === 'string' ? primero.id : '';
  if (/^[A-Za-z0-9_.=:+/-]{1,120}$/.test(id)) return { json: { ...base, resultado: 'aceptado', idMeta: id } };
  return incierto();
}

const err = (cuerpo.error && typeof cuerpo.error === 'object') ? cuerpo.error : {};
if (p.canal === 'rele') {
  const wm = typeof err.codigo === 'string' ? err.codigo : '';
  if (estado === 504 || ['WM-3041', 'WM-3035', 'WM-3030', 'WM-3042'].includes(wm)) return incierto();
  if (wm === '') return (estado >= 500 || !Number.isFinite(estado)) ? incierto() : rechazo('HTTP-' + estado, false);
  // WM-3040: Meta rechazo; el codigo de Meta (131047...) manda sobre el del rele.
  const codigo = err.metaCodigo !== undefined && err.metaCodigo !== null ? err.metaCodigo : wm;
  const reintentable = err.reintentable === true || wm === 'WM-3037' || wm === 'WM-3038';
  return rechazo(codigo, reintentable);
}

// Graph directo: un 5xx o una respuesta sin codigo no dice si salio.
if (!(estado >= 400 && estado < 500) || (typeof err.code !== 'number' && typeof err.code !== 'string')) return incierto();
const codigoMeta = err.code;
return rechazo(codigoMeta, Number(codigoMeta) === 130429 || err.is_transient === true);

// SALIDA DE PERSONA, paso 7: ¿se confirmo todo?, y ¿hay otra vuelta?
//
// Entra la respuesta de `confirmarSalidaPersona` de cada mensaje del lote (el nodo
// HTTP ya las proceso TODAS antes de llegar aqui). Si alguna confirmacion no fue
// un 200 con ok, la ejecucion FALLA con un mensaje que nombra el mensaje y el
// resultado (nunca el texto ni el telefono): una confirmacion perdida es un error
// visible, no un exito falso. El mensaje queda `enviando` y el siguiente reclamo
// lo pasa a `incierto` a los 2 minutos; nunca se reenvia solo.
//
// Sin fallas: sale UN item que vuelve a `Reclamar`. El bucle termina cuando el
// reclamo llega vacio (`Planificar lote` no emite nada) o al llegar al tope de
// vueltas de `Config base` (lo que quede pendiente lo toma el barrido).
const cfg = $('Config base').first().json;
const enviados = $('Resultado del envío').all();
const fallas = [];
$input.all().forEach((it, i) => {
  const r = it.json || {};
  const cuerpo = (r.body && typeof r.body === 'object') ? r.body : {};
  if (Number(r.statusCode) !== 200 || cuerpo.ok !== true) {
    const e = enviados[i] ? enviados[i].json : {};
    fallas.push(`${String(e.mensajeId ?? '?')} (${String(e.resultado ?? '?')}) -> HTTP ${String(r.statusCode ?? 'sin respuesta')}`);
  }
});
if (fallas.length > 0) {
  throw new Error('Salida de persona: no se pudo confirmar ' + fallas.length + ' mensaje(s): ' + fallas.join('; '));
}

const tope = Math.max(1, Math.min(50, Number(cfg.maxVueltas) || 10));
if ($runIndex + 1 >= tope) return [];
return [{ json: { vuelta: $runIndex + 1 } }];
